'use client';

import { useState, useEffect } from 'react';
import { revalidatePath } from 'next/cache';
import { useRouter } from 'next/navigation';

export default function Home() {
  const [isNotificationsEnabled, setIsNotificationsEnabled] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const router = useRouter();

  // Load initial preference
  useEffect(() => {
    const saved = localStorage.getItem('notificationsEnabled');
    if (saved) {
      setIsNotificationsEnabled(JSON.parse(saved));
    }
  }, []);

  const toggleNotifications = async () => {
    setIsLoading(true);

    try {
      // Call the Server Action
      await toggleNotificationPreference(!isNotificationsEnabled);

      // Refresh the current page to show updated preference
      router.refresh();
    } catch (error) {
      console.error('Failed to toggle notifications:', error);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <main className="max-w-md mx-auto mt-10 p-6 bg-white rounded-lg shadow-md">
      <h1 className="text-2xl font-bold mb-6">Settings</h1>

      <div className="flex items-center justify-between p-4 border rounded-lg">
        <div>
          <h2 className="font-medium">Notifications</h2>
          <p className="text-sm text-gray-600">
            Enable or disable push notifications
          </p>
        </div>

        <button
          onClick={toggleNotifications}
          disabled={isLoading}
          className={`relative inline-flex h-6 w-11 items-center rounded-full transition-colors ${
            isNotificationsEnabled ? 'bg-blue-600' : 'bg-gray-200'
          } ${isLoading ? 'opacity-50 cursor-not-allowed' : 'cursor-pointer'}`}
        >
          <span
            className={`inline-block h-4 w-4 transform rounded-full bg-white transition-transform ${
              isNotificationsEnabled ? 'translate-x-6' : 'translate-x-1'
            }`}
          />
        </button>
      </div>

      <div className="mt-4 text-sm text-gray-500">
        Current status: {isNotificationsEnabled ? 'Enabled' : 'Disabled'}
      </div>
    </main>
  );
}

// Server Action
async function toggleNotificationPreference(enabled: boolean) {
  'use server';

  // In a real application, this would update a database
  // For this demo, we'll just simulate an async operation
  await new Promise(resolve => setTimeout(resolve, 500));

  // Store the preference (in a real app, this would be in a database)
  // We can't directly access localStorage from server, so this is just for demonstration
  // In practice, you'd save this to your database here

  // Revalidate the current page to trigger a refresh with updated data
  revalidatePath('/');

  return { success: true, enabled };
}

